<?php $edit=!empty($customer['id']);?><h1 class="h"><?=$edit?'Upravit zákazníka':'Nový zákazník'?></h1><div class="sub">Firemní i soukromé kontakty. IČO lze doplnit přes ARES.</div><form class="form" method="post" action="<?=$edit?'/customers/'.$customer['id'].'/update':'/customers/save'?>"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><div class="field"><label>Typ</label><select name="type"><option value="company" <?=($customer['type']??'company')==='company'?'selected':''?>>Firma</option><option value="person" <?=($customer['type']??'')==='person'?'selected':''?>>Osoba</option></select></div><div class="field"><label>IČO</label><input name="ico" value="<?=View::e($customer['ico']??'')?>"></div></div><div class="field"><label>Název firmy</label><input name="company_name" value="<?=View::e($customer['company_name']??'')?>"></div><div class="row"><div class="field"><label>Jméno</label><input name="first_name" value="<?=View::e($customer['first_name']??'')?>"></div><div class="field"><label>Příjmení</label><input name="last_name" value="<?=View::e($customer['last_name']??'')?>"></div></div><div class="row"><div class="field"><label>DIČ</label><input name="dic" value="<?=View::e($customer['dic']??'')?>"></div><div class="field"><label>E-mail</label><input type="email" name="email" value="<?=View::e($customer['email']??'')?>"></div></div><div class="row"><div class="field"><label>Telefon</label><input name="phone" value="<?=View::e($customer['phone']??'')?>"></div><div class="field"><label>Web</label><input name="web" value="<?=View::e($customer['web']??'')?>"></div></div><div class="row"><div class="field"><label>Ulice</label><input name="street" value="<?=View::e($customer['street']??'')?>"></div><div class="field"><label>Město</label><input name="city" value="<?=View::e($customer['city']??'')?>"></div></div><div class="row"><div class="field"><label>Dodací ulice</label><input name="delivery_street" value="<?=View::e($customer['delivery_street']??'')?>"></div><div class="field"><label>Dodací město</label><input name="delivery_city" value="<?=View::e($customer['delivery_city']??'')?>"></div></div><div class="field"><label>Poznámka</label><textarea name="note"><?=View::e($customer['note']??'')?></textarea></div><?php if(!$edit):?><label><input type="checkbox" name="ares" value="1"> při uložení doplnit údaje z ARES</label><?php endif;?><button class="btn primary"><?=$edit?'Uložit změny':'Uložit zákazníka'?></button></form>